// 1. Ingest learner query and strictly validate payload
const body = $json.body || $json;
const headers = $json.headers || {};
const query = (body.query_text || '').trim();
const learnerId = (body.learner_id || '').trim();

if (!learnerId) {
  throw new Error("Bad Request: 'learner_id' is required and cannot be blank or unassigned.");
}
if (!query) {
  throw new Error("Bad Request: 'query_text' cannot be blank or contain only whitespace.");
}

const startTime = Date.now();

// Distributed execution tracing: client-supplied or generated
const correlationId = headers['x-correlation-id'] || headers['X-Correlation-ID'] || body.correlation_id || ('corr-' + startTime.toString(36) + '-' + Math.random().toString(36).substring(2, 7));

// Idempotency Key Handling:
// Priority 1: Client-supplied explicit Idempotency-Key (via HTTP Header or request JSON body)
// Used when client retries the exact same transaction over the network.
// Priority 2: Distinct transaction UUID generated for each new incoming student request.
// Guarantees that when a student asks the same question after their issue was resolved,
// a brand-new ticket is created rather than getting blocked by an old key!
let idempotencyKey = headers['idempotency-key'] || headers['Idempotency-Key'] || body.idempotency_key;
if (!idempotencyKey) {
  idempotencyKey = 'idemp-tx-' + startTime.toString(36) + '-' + Math.random().toString(36).substring(2, 10).toUpperCase() + Math.random().toString(36).substring(2, 10).toUpperCase();
}

return {
  learner_id: learnerId,
  query_text: query,
  cohort_city: body.cohort_city || 'Cairo',
  correlation_id: correlationId,
  idempotency_key: idempotencyKey,
  start_time: startTime,
  received_at: new Date(startTime).toISOString()
};

// Prepare Escalate Response to Learner with strict DB persistence check and True E2E Latency
const prev = $('Analyze Sentiment, NER & Vector RAG').first().json;
const parseNode = $('Parse & Validate Query').first().json;
const dbResult = $json;

// Ensure database actually recorded the escalation ticket
const isPersisted = Boolean(dbResult && dbResult.status === 'persisted' && dbResult.ticket_id);
if (!isPersisted) {
  throw new Error("Database escalation ticket persistence failed. Immediate manual mentor alert required.");
}

// True End-to-End Workflow Execution Latency (measured from Webhook entry)
const totalLatencyMs = Math.round(Date.now() - (parseNode.start_time || Date.now()));
const slaMet = totalLatencyMs < 3500;

return {
  status: 'escalated',
  ticket_id: dbResult.ticket_id,
  learner_id: prev.learner_id,
  correlation_id: parseNode.correlation_id || prev.correlation_id || ('corr-' + Date.now().toString(36)),
  idempotency_key: parseNode.idempotency_key || dbResult.idempotency_key || ('idemp-' + Date.now().toString(36)),
  idempotent_deduplicated: Boolean(dbResult.idempotent_deduplicated),
  assigned_queue: prev.assigned_queue,
  priority: prev.priority,
  db_persisted: true,
  sentiment: prev.sentiment,
  response_message: prev.agent_response,
  execution_latency_ms: totalLatencyMs,
  sla_met: slaMet
};

// Prepare Automated Semantic Retrieval Response with True E2E Latency and Unique Ticket ID
const data = $json;
const parseNode = $('Parse & Validate Query').first().json;

const totalLatencyMs = Math.round(Date.now() - (parseNode.start_time || Date.now()));
const slaMet = totalLatencyMs < 3500;
const uniqueAutoId = 'TCK-AUTO-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).substring(2, 7).toUpperCase();

return {
  status: 'resolved_auto',
  ticket_id: uniqueAutoId,
  learner_id: data.learner_id,
  correlation_id: parseNode.correlation_id || data.correlation_id || ('corr-' + Date.now().toString(36)),
  idempotency_key: parseNode.idempotency_key || ('idemp-' + Date.now().toString(36)),
  assigned_queue: data.assigned_queue,
  priority: data.priority,
  db_persisted: false,
  extracted_modules: data.extracted_modules,
  extracted_dates: data.extracted_dates,
  retrieved_chunk: data.retrieved_chunk,
  response_message: data.agent_response,
  execution_latency_ms: totalLatencyMs,
  sla_met: slaMet
};
